// Gardener check: no installed skill or manifest artifact tells an agent to write or run automated
// tests. Negation is action-scoped: a directive is allowed only when a negation sits directly before
// the matched action, with at most one word between ("do not write a regression test"); a negation
// elsewhere in the clause ("Do not skip lint, then run tests") or after it ("Write tests without
// mocks") does not excuse it.
const directiveTestInstructions = [
  /\b(?:pnpm|npm|yarn|bun)(?: run)? test(?::[\w-]+)?\b/gi, /then tests\b/gi, /focused tests/gi, /A test covers/gi, /test coverage/gi,
  /\b(?:add|write|create|require|keep|preserve)s? (?:a |new |focused |more |the |existing )?(?:unit |e2e |regression |integration )?(?:tests?|test files|test suites?)\b/gi,
  /\brun (?:the |all |your |existing |focused )?(?:unit |e2e |integration |regression )?tests\b/gi,
  /\b(?:vitest|jest|playwright test|node --test|pytest)\b/gi,
  /missing tests/gi, /\btest executor\b/gi,
  /\btestab(?:le|ility)\b/gi, /\btest (?:surface|seams?|locality)\b/gi, /\bunit\/contract\/integration\b/gi,
];
/** @param {string} before */
const negatedClause = before => /(?:\b(?:no|not|never|without|nor|avoid)\b|n't\b)(?:\s+\w+)?\s*$/i.test(before);
const instructionFiles = new Set(manifest.artifacts.map((/** @type {{sourcePath:string}} */ artifact) => resolve(root, artifact.sourcePath)));
for (const directory of new Set(catalog.skills.flatMap((/** @type {any} */ skill) => skill.variants.map((/** @type {any} */ variant) => variant.sourceDirectory)))) {
  for (const file of await files(directory)) instructionFiles.add(file);
}
/** @type {string[]} */ const directiveHits = [];
for (const file of [...instructionFiles].filter(file => /\.(?:md|toml|ya?ml)$/.test(file)).sort()) {
  (await readFile(file, "utf8")).split("\n").forEach((line, index) => {
    const hit = directiveTestInstructions.some(pattern =>
      [...line.matchAll(pattern)].some(match => !negatedClause(line.slice(0, match.index))));
    if (hit) directiveHits.push(`${relative(root, file)}:${index + 1}: ${line.trim()}`);
  });
}
assert(directiveHits.length === 0, `instructions ask for automated tests:\n${directiveHits.join("\n")}`);
await outputJson(`manifests/${version}.json`, manifest);

const pkg = JSON.parse((await bytes("package.json")).toString());
const scripts = pkg.scripts ?? {};
if (pkg.version !== version || pkg.contractVersion !== version
  || scripts["release:prepare"] !== `node ./scripts/build-release-1341.mjs --check`
  || !scripts["skills:audit"]?.includes(`--version ${catalogVersion}`)
  || !scripts["skills:sync"]?.includes(`--version ${catalogVersion}`)
  || scripts.verify !== "pnpm run roster:check && pnpm run typecheck && pnpm run validate:repository && pnpm run release:prepare"
  || scripts["check:no-tests"] !== "./bin/development-system check-no-tests"
  || ["test", "test:acceptance", "measure:test"].some(name => name in scripts)
  || Object.values(scripts).some(command => /node\s+--test\b/.test(String(command)))
  || !pkg.files.includes("claude/") || !pkg.files.includes("runtime/")) {
  throw new Error(`package.json release metadata does not match ${version} / catalog ${catalogVersion}`);
}
console.log(JSON.stringify({ version, previous, catalogVersion, artifacts: manifest.artifacts.length, repointed: updated.size, skills: catalog.skills.length, movedSkills: moved, operation: write ? "write" : "check" }));
